# Rebuild cleanly and trace both paths with an explicit path-length counter.
out2=[row[:] for row in grid]
for r in (1,2):
    for c in (1,2,4,5,7,8,10,11): out2[r][c]=8
for r in (25,26):
    for c in (24,25): out2[r][c]=8

def trace2(sr):
    r,c=sr,0
    out2[r][c]=3
    direction='right'; bg=9; n=0
    while True:
        if direction=='right':
            cc=c+1
            while cc<30 and grid[r][cc]==bg:
                n+=1; out2[r][cc]=[3,3,6][n%3]; cc+=1
            if cc==30: break
            out2[r][cc]=7
            c=cc-1; r-=1; bg=8
            if r<0 or grid[r][c]!=8: break
            direction='up'
        else:
            rr=r
            while rr>=0 and grid[rr][c]==8:
                n+=1; out2[rr][c]=[3,3,6][n%3]; rr-=1
            if rr<0: break
            out2[rr][c]=7
            r=rr+1; c+=1; bg=8
            if c>=30 or grid[r][c]!=8: break
            direction='right'
for sr in (14,26): trace2(sr)
for r in range(30):
    changed=[(c,out2[r][c]) for c in range(30) if out2[r][c]!=grid[r][c]]
    if changed: print(r,changed)
print('dims',len(out2),set(map(len,out2)))
